type Account struct {
	mu      sync.Mutex
	ID      int64
	Balance int64
}

func Transfer(from, to *Account, amount int64) error {
	from.mu.Lock()
	defer from.mu.Unlock()
	to.mu.Lock()
	defer to.mu.Unlock()

	if from.Balance < amount {
		return errors.New("insufficient funds")
	}
	from.Balance -= amount
	to.Balance += amount
	return nil
}
